using Payments;

namespace Payments.Tests;

internal sealed class FakePaymentProvider : IPaymentProvider
{
    public ChargeResult? ChargeResultToReturn { get; set; }
    public RefundResult? RefundResultToReturn { get; set; }
    public Exception? ExceptionToThrow { get; set; }

    public string? LastCardToken { get; private set; }
    public decimal LastAmount { get; private set; }
    public string? LastChargeId { get; private set; }

    public Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        if (ExceptionToThrow is not null)
            throw ExceptionToThrow;

        LastCardToken = cardToken;
        LastAmount = amount;
        return Task.FromResult(ChargeResultToReturn ?? new ChargeResult("chg_default", true));
    }

    public Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        if (ExceptionToThrow is not null)
            throw ExceptionToThrow;

        LastChargeId = chargeId;
        return Task.FromResult(RefundResultToReturn ?? new RefundResult("ref_default", true));
    }
}

using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly FakePaymentProvider _provider;
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new PaymentGateway(_provider);
    }

    // ── Constructor ──────────────────────────────────────────────

    [TestMethod]
    public void Constructor_NullProvider_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => new PaymentGateway(null!));
        Assert.AreEqual("provider", ex.ParamName);
    }

    // ── ChargeAsync ──────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessResult()
    {
        _provider.ChargeResultToReturn = new ChargeResult("chg_123", true);

        var result = await _gateway.ChargeAsync("tok_valid", 50.00m);

        Assert.IsTrue(result.Success);
        Assert.AreEqual("chg_123", result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_PassesParametersToProvider()
    {
        await _gateway.ChargeAsync("tok_abc", 99.95m);

        Assert.AreEqual("tok_abc", _provider.LastCardToken);
        Assert.AreEqual(99.95m, _provider.LastAmount);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderReturnsFailed_ReturnsFalse()
    {
        _provider.ChargeResultToReturn = new ChargeResult("chg_fail", false);

        var result = await _gateway.ChargeAsync("tok_valid", 25.00m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task ChargeAsync_InvalidCardToken_ThrowsArgumentException(string? cardToken)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(cardToken!, 10m));
        Assert.AreEqual("cardToken", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRange(double amount)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_PropagatesException()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("Gateway down");

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.ChargeAsync("tok_valid", 10m));
    }

    // ── RefundAsync ──────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        _provider.RefundResultToReturn = new RefundResult("ref_456", true);

        var result = await _gateway.RefundAsync("chg_123");

        Assert.IsTrue(result.Success);
        Assert.AreEqual("ref_456", result.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_PassesChargeIdToProvider()
    {
        await _gateway.RefundAsync("chg_xyz");

        Assert.AreEqual("chg_xyz", _provider.LastChargeId);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderReturnsFailed_ReturnsFalse()
    {
        _provider.RefundResultToReturn = new RefundResult("ref_fail", false);

        var result = await _gateway.RefundAsync("chg_123");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
        Assert.AreEqual("chargeId", ex.ParamName);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_PropagatesException()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("Refund failed");

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync("chg_123"));
    }

    // ── ProcessWebhook ───────────────────────────────────────────

    [TestMethod]
    [DataRow("charge.succeeded", "Charge confirmed")]
    [DataRow("charge.failed", "Charge failed")]
    [DataRow("refund.completed", "Refund completed")]
    public void ProcessWebhook_KnownEvent_ReturnsProcessed(string eventType, string expectedMessage)
    {
        var result = _gateway.ProcessWebhook(eventType, "{\"id\":\"evt_1\"}");

        Assert.AreEqual(WebhookStatus.Processed, result.Status);
        Assert.AreEqual(expectedMessage, result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_UnknownEvent_ReturnsIgnored()
    {
        var result = _gateway.ProcessWebhook("unknown.event", "{\"id\":\"evt_1\"}");

        Assert.AreEqual(WebhookStatus.Ignored, result.Status);
        Assert.Contains("unknown.event", result.Message);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ProcessWebhook_InvalidEventType_ThrowsArgumentException(string? eventType)
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(eventType!, "payload"));
        Assert.AreEqual("eventType", ex.ParamName);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ProcessWebhook_InvalidPayload_ThrowsArgumentException(string? payload)
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook("charge.succeeded", payload!));
        Assert.AreEqual("payload", ex.ParamName);
    }
}

